const names=['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B'];
const profiles=[[6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88],[6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17]];
export function estimateKey(samples,rate){const n=8192,chroma=new Float64Array(12),hop=Math.max(1,Math.floor(rate/12000));let windows=0;
 for(let w=0;w<24;w++){const start=Math.floor(Math.max(0,samples.length-n*hop)*w/23),re=new Float64Array(n),im=new Float64Array(n);let energy=0;for(let i=0;i<n;i++){const v=samples[start+i*hop]||0;energy+=v*v;re[i]=v*(.5-.5*Math.cos(2*Math.PI*i/(n-1)));}if(energy/n<1e-7)continue;
 let j=0;for(let i=1;i<n;i++){let bit=n>>1;while(j&bit){j^=bit;bit>>=1;}j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]];}
 for(let size=2;size<=n;size<<=1){const wr=Math.cos(-2*Math.PI/size),wi=Math.sin(-2*Math.PI/size);for(let s=0;s<n;s+=size){let r=1,m=0;for(let k=0;k<size/2;k++){const a=s+k,b=a+size/2,tr=r*re[b]-m*im[b],ti=r*im[b]+m*re[b];re[b]=re[a]-tr;im[b]=im[a]-ti;re[a]+=tr;im[a]+=ti;const next=r*wr-m*wi;m=r*wi+m*wr;r=next;}}}
 const mag=Float64Array.from(re.subarray(0,n/2),(v,i)=>Math.hypot(v,im[i])),maximum=Math.max(...mag),frame=new Float64Array(12);for(let i=2;i<mag.length-1;i++){if(mag[i]<maximum*.025||mag[i]<mag[i-1]||mag[i]<mag[i+1])continue;const denominator=mag[i-1]-2*mag[i]+mag[i+1],delta=denominator?Math.max(-.5,Math.min(.5,.5*(mag[i-1]-mag[i+1])/denominator)):0,hz=(i+delta)*(rate/hop)/n;if(hz<45||hz>2200)continue;const note=69+12*Math.log2(hz/440),midi=Math.round(note);if(Math.abs(note-midi)>.35)continue;frame[(midi%12+12)%12]+=mag[i]/Math.sqrt(hz);}
 const sum=frame.reduce((a,b)=>a+b,0);if(sum>1e-8){for(let i=0;i<12;i++)chroma[i]+=frame[i]/sum;windows++;}}
 if(windows<3)return null;const max=Math.max(...chroma);if([...chroma].filter(x=>x>max*.12).length<3)return null;const mean=chroma.reduce((a,b)=>a+b)/12,norm=Math.sqrt(chroma.reduce((a,b)=>a+(b-mean)**2,0));if(norm<1e-7)return null;
 const scores=[];for(let mode=0;mode<2;mode++){const profile=profiles[mode],m=profile.reduce((a,b)=>a+b)/12,d=Math.sqrt(profile.reduce((a,b)=>a+(b-m)**2,0));for(let root=0;root<12;root++){let score=0;for(let i=0;i<12;i++)score+=(chroma[(i+root)%12]-mean)*(profile[i]-m);scores.push({name:names[root]+(mode?'m':''),score:score/(norm*d)});}}scores.sort((a,b)=>b.score-a.score);const gap=scores[0].score-scores[1].score;return scores[0].score>=.6&&gap>=.035?{name:scores[0].name,confidence:scores[0].score*Math.min(1,gap/.15)}:null;
}
if(typeof self!=='undefined'&&typeof document==='undefined')self.onmessage=({data})=>{try{self.postMessage(estimateKey(data.samples,data.rate));}catch{self.postMessage(null);}};
